const fila = $input.first().json || {};
const req = $('Webhook').first().json;
const eanBuscado = String((req.query && req.query.ean) || (req.body && req.body.ean) || '');
const precioRaw = (req.query && req.query.precio) ?? (req.body && req.body.precio);

// Normaliza precios tipo "$ 12.000,50", "12000.5" o 12000
function parsePrecio(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') return v;
  let s = String(v).replace(/[^0-9.,]/g, '');
  const puntos = s.split('.').length - 1;
  if (s.includes(',')) s = s.split('.').join('').replace(',', '.');
  else if (puntos > 1) s = s.split('.').join('');
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
}

const precioUsuario = parsePrecio(precioRaw);

// Producto no encontrado en la hoja
if (Object.keys(fila).length === 0 || !fila.ean) {
  return [{ json: { encontrado: false, ean: eanBuscado, precio_usuario: precioUsuario, score: null, mensaje: 'Producto no encontrado' } }];
}

const min = parsePrecio(fila.precio_min_producto);
const max = parsePrecio(fila.precio_max_producto);
const clamp = (v) => Math.max(0, Math.min(100, v));

// 30% Precio: igual al minimo = 100, igual al maximo = 0
let scorePrecio = null;
if (precioUsuario !== null && precioUsuario > 0 && min !== null && max !== null) {
  if (max > min) scorePrecio = clamp((max - precioUsuario) / (max - min) * 100);
  else scorePrecio = precioUsuario <= min ? 100 : 0;
}

// 15% Promociones: sin datos de promo todavia, se excluye del calculo
const tienePromo = false;
const scorePromo = null; // futuro: descuento o cercania al vencimiento

// Sin datos en la hoja todavia (se excluyen y se reparte su peso)
const scoreRating = null;   // futuro: (rating / 5) * 100
const scoreReviews = null;  // futuro: Math.min(100, Math.log10(n + 1) / 3 * 100)
const scoreCrecimiento = null;

const partes = [
  [0.30, scorePrecio],
  [0.25, scoreRating],
  [0.20, scoreReviews],
  [0.15, scorePromo],
  [0.10, scoreCrecimiento],
].filter((p) => p[1] !== null);

let score = null;
if (scorePrecio !== null) {
  const pesoTotal = partes.reduce((s, p) => s + p[0], 0);
  score = Math.round(partes.reduce((s, p) => s + p[0] * p[1], 0) / pesoTotal * 10) / 10;
}

return [{
  json: {
    encontrado: true,
    ean: String(fila.ean),
    nombre: fila.producto,
    marca: fila.marca,
    categoria: fila.categoria,
    comercio: fila.comercio,
    imagen_url: fila.imagen,
    precio_usuario: precioUsuario,
    precio_lista: parsePrecio(fila.precio_lista),
    precio_min: min,
    precio_max: max,
    tiene_promo: tienePromo,
    score_precio: scorePrecio === null ? null : Math.round(scorePrecio * 10) / 10,
    score_promociones: scorePromo,
    score: score,
    mensaje: score === null ? 'Falta el precio ingresado para calcular el score' : 'ok',
  },
}];
